import{_ as a,a as t,c as r,ac as l}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"文件与文本转换的输入输出约定","description":"路径、编码、CSV、流式处理、输出创建、错误和跨Shell差异。","frontmatter":{"title":"文件与文本转换的输入输出约定","description":"路径、编码、CSV、流式处理、输出创建、错误和跨Shell差异。","showdocs":{"topics":[{"id":"cli","title":"文件与文本处理","link":"/topics/cli/"}],"kind":"文件与文本处理上手与对象","scope":"general","audience":"general","group":"工程与工具","seriesTitle":"文件与文本处理：路径、编码与流式变换","summary":"路径、编码、CSV、流式处理、输出创建、错误和跨Shell差异。","status":"active","related":[{"title":"包管理、字体与环境工具命令","link":"/tools/command-tools/cli/reference/cli-packages-general-general","kind":"文件与文本处理任务与配置","scope":"general","audience":"general"},{"title":"编译构建、测试与运行诊断命令","link":"/tools/command-tools/cli/reference/cli-development-general-general-2","kind":"文件与文本处理任务与配置","scope":"general","audience":"general"},{"title":"编译构建、测试与运行诊断命令 · 编译、链接与执行项目构建至格式化代码与删除未使用导入","link":"/tools/command-tools/cli/reference/cli-development-general-general-2-part-01","kind":"文件与文本处理任务与配置","scope":"general","audience":"general"},{"title":"编译构建、测试与运行诊断命令 · 生成文档、整理上下文与分享代码图至专用开发环境","link":"/tools/command-tools/cli/reference/cli-development-general-general-2-part-03","kind":"文件与文本处理任务与配置","scope":"general","audience":"general"},{"title":"编译构建、测试与运行诊断命令 · 运行测试、工作流与性能测量至从 Java 进程和线程定位运行问题","link":"/tools/command-tools/cli/reference/cli-development-general-general-2-part-02","kind":"文件与文本处理任务与配置","scope":"general","audience":"general"}],"prev":false,"next":{"text":"文件与文本处理：完整实践与解答","link":"/tools/command-tools/cli/practice/application"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":false,"next":{"text":"文件与文本处理：完整实践与解答","link":"/tools/command-tools/cli/practice/application"}},"headers":[],"relativePath":"tools/command-tools/cli/file-and-text-processing.md","filePath":"tools/command-tools/cli/file-and-text-processing.md"}'),o={name:"tools/command-tools/cli/file-and-text-processing.md"};function n(i,e,s,c,p,d){return t(),r("div",null,[...e[0]||(e[0]=[l('<h1 id="文件与文本转换的输入输出约定" tabindex="-1">文件与文本转换的输入输出约定 <a class="header-anchor" href="#文件与文本转换的输入输出约定" aria-label="Permalink to &quot;文件与文本转换的输入输出约定&quot;">​</a></h1><h2 id="part-1" tabindex="-1">选择输入与匹配方式 <a class="header-anchor" href="#part-1" aria-label="Permalink to &quot;选择输入与匹配方式 {#part-1}&quot;">​</a></h2><p>本页解释如何把含 name、minutes 两列的 CSV 转成 JSON 数组。对应的输入、完整程序与预期结果见<a href="/tools/command-tools/cli/practice/application#source">完整实践</a>；文中的“本例”均指该程序。示例未在本轮运行。</p><h3 id="part-1-paths" tabindex="-1">确定输入输出路径 <a class="header-anchor" href="#part-1-paths" aria-label="Permalink to &quot;确定输入输出路径 {#part-1-paths}&quot;">​</a></h3><p>路径先确定绝对路径、当前目录和输入输出边界。相对路径依赖进程cwd，含空格的路径必须作为单个参数传递；不要拼接Shell命令处理用户文件名。</p><h3 id="part-1-encoding" tabindex="-1">读取 UTF-8 与 BOM <a class="header-anchor" href="#part-1-encoding" aria-label="Permalink to &quot;读取 UTF-8 与 BOM {#part-1-encoding}&quot;">​</a></h3><p>UTF-8时明确输入编码与错误策略。本例使用utf-8-sig读取兼容BOM，用utf-8写出；解码失败应报告位置，不默认忽略非法字节造成静默数据丢失。</p><h3 id="part-1-csv" tabindex="-1">正确解析 CSV 引号 <a class="header-anchor" href="#part-1-csv" aria-label="Permalink to &quot;正确解析 CSV 引号 {#part-1-csv}&quot;">​</a></h3><p>CSV引号应交给csv模块，字段可能包含逗号、双引号和换行。简单split逗号会破坏这些记录；newline空字符串允许模块正确处理换行，不能把物理行数当记录数。</p><p><span id="part-3-sources"></span></p><p><span id="part-2-sources"></span></p><h3 id="part-1-sources" tabindex="-1">依据与适用范围 <a class="header-anchor" href="#part-1-sources" aria-label="Permalink to &quot;依据与适用范围 {#part-1-sources}&quot;">​</a></h3><ul><li><a href="https://docs.python.org/3/library/csv.html" target="_blank" rel="noopener noreferrer">本课官方依据</a>，资料核对日2026-10-17。</li></ul><p>本课完成的是列明任务的理论与静态资料，不代表产品全部能力或三平台运行通过。历史文档保留旧URL；涉及账号、版本、价格与界面位置时，以对应官方资料及实际授权环境为准。</p><h2 id="part-2" tabindex="-1">完成转换并保存结果 <a class="header-anchor" href="#part-2" aria-label="Permalink to &quot;完成转换并保存结果 {#part-2}&quot;">​</a></h2><h3 id="part-2-streams" tabindex="-1">按记录读取与内存边界 <a class="header-anchor" href="#part-2-streams" aria-label="Permalink to &quot;按记录读取与内存边界 {#part-2-streams}&quot;">​</a></h3><p>流式读取按记录迭代减少峰值内存，但排序或全量去重仍可能保存大量状态。输入大小无上限时先定义资源预算，不以使用迭代器就宣称常量内存。</p><h3 id="part-2-output" tabindex="-1">防止覆盖原输入 <a class="header-anchor" href="#part-2-output" aria-label="Permalink to &quot;防止覆盖原输入 {#part-2-output}&quot;">​</a></h3><p>输出覆盖要避免输入与输出同一路径。独占创建模式x在目标存在时拒绝写入，比先exists再写更直接；写入失败仍可能留下部分文件，恢复前先检查内容。</p><h3 id="part-2-errors" tabindex="-1">定位格式与字段错误 <a class="header-anchor" href="#part-2-errors" aria-label="Permalink to &quot;定位格式与字段错误 {#part-2-errors}&quot;">​</a></h3><p>错误分类区分格式不合法、字段缺失和业务值非法。CSV列存在不等于金额能解析；报告记录编号和字段名帮助定位，日志不要输出含个人信息的整条记录。</p><h2 id="part-3" tabindex="-1">处理失败与规模限制 <a class="header-anchor" href="#part-3" aria-label="Permalink to &quot;处理失败与规模限制 {#part-3}&quot;">​</a></h2><h3 id="part-3-newlines" tabindex="-1">区分 CRLF 与 LF <a class="header-anchor" href="#part-3-newlines" aria-label="Permalink to &quot;区分 CRLF 与 LF {#part-3-newlines}&quot;">​</a></h3><p>CRLF与LF是字节层面的行结束差异。文本读取可能规范化换行，二进制校验则保持原字节；做内容转换还是做原件归档要先区分，否则摘要变化会被误当数据损坏。</p><h3 id="part-3-numbers" tabindex="-1">拒绝负数与非有限数字 <a class="header-anchor" href="#part-3-numbers" aria-label="Permalink to &quot;拒绝负数与非有限数字 {#part-3-numbers}&quot;">​</a></h3><p>非有限数字时NaN和Infinity虽然某些解析器接受，但不是本例允许的分钟数。Decimal.is_finite配合非负检查拒绝它们，输出用十进制字符串避免浮点舍入改变账面值。</p><h3 id="part-3-shell" tabindex="-1">使用显式文件参数 <a class="header-anchor" href="#part-3-shell" aria-label="Permalink to &quot;使用显式文件参数 {#part-3-shell}&quot;">​</a></h3><p>Shell差异会影响通配符展开、引号与管道编码。PowerShell对象管道与Bash字节流不同，本例用显式文件参数绕开管道假设；命令文本只供阅读，本轮没有执行。</p>',28)])])}const m=a(o,[["render",n]]);export{u as __pageData,m as default};
